// Diagnostique la généralisation à partir des scores train et validation.
// TODO : ne regarder que la validation rate l'overfitting — il faut comparer
//        train ET val (un train excellent + val faible = mémorisation).
export function diagnose(scores) {
  return scores.val < 70 ? 'underfit' : 'good';
}

